onClick:
{{
  (() => {
    const fechaOk = Boolean(DatePicker5.formattedDate);
    const sectorOk = Boolean(Input1.text && Input1.text.trim() !== "");
    const detalleOk = Boolean(Input3.text && Input3.text.trim() !== "");
    const totalNum = Number(Input2.text);
    const totalOk = Input2.text !== "" && !Number.isNaN(totalNum) && totalNum > 0;

    if (!fechaOk || !sectorOk || !detalleOk || !totalOk) {
      showAlert("Completá fecha, sector, detalle y un total mayor a 0 antes de guardar.", "warning");
      return;
    }

    const queryAGuardar = appsmith.store.modoGasto === "editar" ? Update_gastos : Insert_gastos;

    queryAGuardar.run(
      () => {
        Select_public_gastos1.run();
        Total_record_public_gastos1.run();
        closeModal("Modal1");
      },
      (error) => {
        showAlert("No se pudo guardar el gasto: " + error.message, "error");
      }
    );
  })()
}}
